ted_at" timestamp with time zone default now(),"tax_number" text,"tax_mode" text default 'taxable'::text,"deposit_requested_amount" numeric default 0,"deposit_requested_at" timestamp with time zone,"deposit_status" text default 'none'::text,"deposit_note" text,"import_reviewed" boolean default false);create table if not exists public.invoice_line_items("id" uuid primary key default gen_random_uuid(),"invoice_id" uuid,"business_id" uuid,"description" text default ''::text,"quantity" numeric default 1,"unit_price" numeric default 0,"line_total" numeric default 0,"sort_order" integer default 0,"created_at" timestamp with time zone default now());create table if not exists public.activity_logs("id" uuid primary key default gen_random_uuid(),"business_id" uuid,"actor_user_id" uuid,"actor_email" text,"action" text,"entity_type" text,"entity_id" uuid,"entity_label" text,"details" jsonb default '{}'::jsonb,"created_at" timestamp with time zone default now());grant usage on schema public,auth to anon,authenticated,service_role;grant all on all tables in schema public to service_role;grant select on auth.users to service_role;
